import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"QEMU debugging techniques","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/qemu-debugging.md","filePath":"troubleshooting/qemu-debugging.md"}'),i={name:"troubleshooting/qemu-debugging.md"};function o(r,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="qemu-debugging-techniques" tabindex="-1">QEMU debugging techniques <a class="header-anchor" href="#qemu-debugging-techniques" aria-label="Permalink to &quot;QEMU debugging techniques&quot;">​</a></h1><h2 id="capture-everything" tabindex="-1">Capture everything <a class="header-anchor" href="#capture-everything" aria-label="Permalink to &quot;Capture everything&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>The serial log IS the boot narrative - one <code>OK</code> per subsystem.</p><h2 id="watch-the-machine-not-just-the-guest" tabindex="-1">Watch the machine, not just the guest <a class="header-anchor" href="#watch-the-machine-not-just-the-guest" aria-label="Permalink to &quot;Watch the machine, not just the guest&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-d int,cpu_reset,guest_errors -D qemu.log    (interrupts/resets/errors)</span></span>
<span class="line"><span>-monitor stdio                               (QEMU monitor alongside)</span></span></code></pre></div><h2 id="gdb-into-the-kernel" tabindex="-1">GDB into the kernel <a class="header-anchor" href="#gdb-into-the-kernel" aria-label="Permalink to &quot;GDB into the kernel&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -s -S        # gdb stub, frozen at reset</span></span>
<span class="line"><span>gdb build/opencube_base.elf          # the pre-strip ELF has symbols</span></span>
<span class="line"><span>(gdb) target remote localhost:1234</span></span>
<span class="line"><span>(gdb) break kmain</span></span>
<span class="line"><span>(gdb) continue</span></span></code></pre></div><p><code>build/opencube_base.elf</code> is kept by <code>make kernel</code> precisely for this - the final <code>build/opencube.elf</code> is stripped.</p><h2 id="deterministic-replays" tabindex="-1">Deterministic replays <a class="header-anchor" href="#deterministic-replays" aria-label="Permalink to &quot;Deterministic replays&quot;">​</a></h2><p>The build is reproducible - the same tree produces byte-identical ELFs, so a crash you can reproduce twice is the same bytes both times. Combine with QEMU&#39;s own <code>-icount</code> for timing stability in network tests.</p><h2 id="device-matrix-at-a-glance" tabindex="-1">Device matrix at a glance <a class="header-anchor" href="#device-matrix-at-a-glance" aria-label="Permalink to &quot;Device matrix at a glance&quot;">​</a></h2><p>The QEMU flags that light up each driver family are tabulated in the <a href="./../drivers/storage.html">driver manuals</a> - attach exactly the device you&#39;re debugging.</p>`,13)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
